export function getOffTheCameraPostBySlug(slug) {
  return offTheCameraPosts.find((post) => post.slug === slug) ?? null
}

export function getOffTheCameraAdjacent(slug) {
  const index = offTheCameraPosts.findIndex((post) => post.slug === slug)
  if (index < 0) return { prev: null, next: null }
  return {
    prev: index > 0 ? offTheCameraPosts[index - 1] : null,
    next: index < offTheCameraPosts.length - 1 ? offTheCameraPosts[index + 1] : null,
  }
}

export function getOffTheCameraRelated(slug, limit = 4) {
  return offTheCameraPosts.filter((post) => post.slug !== slug).slice(0, limit)
}

